def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def _validate(name, lessons, questions, want_ch):
    problems = []
    if len(lessons) != want_ch:
        problems.append(f"  {name}: {len(lessons)} lessons (want {want_ch})")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in lessons if len(l["html"]) < 2500]
    if short:
        problems.append(f"  {name} below depth: {short}")
    if len(questions) != 35:
        problems.append(f"  {name}: {len(questions)} questions (want 35)")
    for q in questions:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  {name} malformed '{q['q'][:40]}'")
    if "ERPNext" in json.dumps({"l": lessons, "q": questions}):
        problems.append(f"  {name}: ERPNext branding leakage")
    return problems


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)

    if '"3.173.0"' in init:
        print("Already applied. Nothing to do.")
        return
    if '"3.172.0"' not in init:
        sys.exit("ABORT: not at v3.172.0.")
    for k in ("payroll_function", "exits_special", "advanced_payroll"):
        if k not in data:
            sys.exit(f"ABORT: {k} module not found in data file.")

    problems = _validate("PAY7", LESSONS_P7, QUESTIONS_P7, 9) + _validate("PAY8", LESSONS_P8, QUESTIONS_P8, 9)
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    # --- PAY1 "costume" voice patch ---
    p1 = data["payroll_function"]
    patched = 0
    for lesson in p1["lessons"]:
        if PAY1_TEXT_OLD in lesson["html"]:
            lesson["html"] = lesson["html"].replace(PAY1_TEXT_OLD, PAY1_TEXT_NEW)
            patched += 1
    for q in p1["questions"]:
        for i, opt in enumerate(q["opts"]):
            if opt == PAY1_Q_OLD:
                q["opts"][i] = PAY1_Q_NEW
                patched += 1
    if "costume" in json.dumps(p1).lower():
        sys.exit("ABORT: PAY1 costume patch incomplete.")
    print(f"PAY 1 voice patch: {patched} replacement(s), 'costume' cleared")

    for name, lessons, questions, key, desc in (
        ("PAY 7", LESSONS_P7, QUESTIONS_P7, "exits_special",
         "Exits in ZhiftERP: the Relieving Date and Status as the exit's first records and the two payment shapes; the final slip's proration with the five-document preview and the statutory tail; Leave Encashment from policy line to record with the start-of-exit balance confirmation; the settlement sheet's two columns and the Full and Final Statement with the leaver's signature before release; closing loans, advances, and recoveries with the insufficient case's owner-decision lane; the ten-line release checklist including same-day access closure; and the special cases on the one operator's rule."),
        ("PAY 8", LESSONS_P8, QUESTIONS_P8, "advanced_payroll",
         "The structural close of the Payroll track: the full Payroll Settings walk — payroll basis, unmarked attendance, holidays in working days, rounding, leave balances on slips, posting granularity — recorded with reasons; the control register assembling the track's separations, reconciliations, registers, and calendars; structure versioning with period-boundary scheduling; the payroll year — slab and applicability re-reads, annual PAYE certificates, returns, the year file; the six-question audit answered from one folder; multi-company payroll; the handover and absence tests; and the track's eight laws."),
    ):
        bank = rebalance(list(questions))
        dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
        if max(dist.values()) > 10:
            print(f"ABORT — {name} spread failed: {dist}")
            sys.exit(1)
        total = sum(len(l["html"]) for l in lessons)
        print(f"{name} v3: {len(lessons)} chapters ({total:,} chars, min {min(len(l['html']) for l in lessons):,}), bank {len(bank)}, spread {dist}")
        if not CHECK_ONLY:
            data[key]["lessons"] = lessons
            data[key]["questions"] = bank
            data[key]["desc"] = desc

    if CHECK_ONLY:
        print("--check given; no files written (PAY1 patch also not written).")
        return

    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.172.0"', '"3.173.0"'))
    print("  data: PAYROLL 7 + 8 lessons + banks REPLACED (style v3) — Payroll track redo COMPLETE")
    print("wrote __version__ -> 3.173.0")


if __name__ == "__main__":
    main()
